import gurobipy as gp
from gurobipy import GRB
LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '1', 'Q': '1000', 'S': '500', 'C': '2.0', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '2', 'Q': '800', 'S': '300', 'C': '3.0', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '3', 'Q': '1200', 'S': '400', 'C': '2.5', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '4', 'Q': '600', 'S': '250', 'C': '3.0', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '5', 'Q': '900', 'S': '450', 'C': '2.2', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '6', 'Q': '700', 'S': '280', 'C': '2.8', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '7', 'Q': '1100', 'S': '420', 'C': '2.4', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '8', 'Q': '500', 'S': '200', 'C': '3.2', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '9', 'Q': '1000', 'S': '480', 'C': '2.1', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture6/parameters.csv', 'values': {'truck_id': '10', 'Q': '650', 'S': '260', 'C': '2.9', 'd1': '1500', 'd2': '2000', 'd3': '1800', 'd4': '1000'}}]
trucks = []
Q = {}
S = {}
C = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    tid = str(v['truck_id'])
    trucks.append(tid)
    Q[tid] = float(v['Q'])
    S[tid] = float(v['S'])
    C[tid] = float(v['C'])
periods = ['1', '2', '3', '4']
demand = {}
for t in periods:
    demand[t] = float(LEGACY_RECORDS[0]['values']['d' + t])
m = gp.Model('Truck_Scheduling')
y_vars = m.addVars(trucks, periods, vtype=GRB.BINARY, name='')
z_vars = m.addVars(trucks, periods, vtype=GRB.BINARY, name='')
x_vars = m.addVars(trucks, periods, lb=0, vtype=GRB.CONTINUOUS, name='')
y0 = {i: 0 for i in trucks}
x0 = {i: 0 for i in trucks}
m.setObjective(gp.quicksum((S[i] * z_vars[i, t] + C[i] * x_vars[i, t] for i in trucks for t in periods)), GRB.MINIMIZE)
for i in trucks:
    for idx, t in enumerate(periods):
        t_int = int(t)
        prev_t = str(t_int - 1)
        y_prev = y0[i] if prev_t == '0' else y_vars[i, prev_t]
        m.addConstr(z_vars[i, t] >= y_vars[i, t] - y_prev)
        m.addConstr(z_vars[i, t] <= 1 - y_prev)
        m.addConstr(z_vars[i, t] <= y_vars[i, t])
    m.addConstr(z_vars[i, '4'] == 0)
for i in trucks:
    for t in ['1', '2', '3']:
        t_next = str(int(t) + 1)
        m.addConstr(y_vars[i, t_next] >= z_vars[i, t])
for i in trucks:
    for t in ['1', '2']:
        t_int = int(t)
        t_prev = str(t_int - 1)
        t1 = str(t_int + 1)
        t2 = str(t_int + 2)
        y_prev = y0[i] if t_prev == '0' else y_vars[i, t_prev]
        m.addConstr(y_prev - y_vars[i, t] <= 1 - y_vars[i, t1])
        m.addConstr(y_prev - y_vars[i, t] <= 1 - y_vars[i, t2])
for i in trucks:
    for t in periods:
        m.addConstr(x_vars[i, t] <= Q[i] * y_vars[i, t])
        m.addConstr(x_vars[i, t] >= 0)
for i in trucks:
    for idx, t in enumerate(periods):
        t_int = int(t)
        prev_t = str(t_int - 1)
        x_prev = x0[i] if prev_t == '0' else x_vars[i, prev_t]
        m.addConstr(x_vars[i, t] - x_prev <= 300)
        m.addConstr(x_prev - x_vars[i, t] <= 300)
for t in periods:
    m.addConstr(gp.quicksum((x_vars[i, t] for i in trucks)) >= demand[t])
for t in periods:
    m.addConstr(gp.quicksum((x_vars[i, t] for i in trucks)) <= 0.9 * gp.quicksum((Q[i] * y_vars[i, t] for i in trucks)))
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')